import {
  ArrowLeft,
  ArrowRight,
  Layers3,
  PenLine,
  SquarePen,
} from "lucide-react";
import { useEffect, useMemo, type CSSProperties } from "react";
import { useNavigate } from "react-router-dom";
import {
  knowledgeAttemptsForBook,
  useKnowledge,
} from "../../store/knowledge";
import SpotlightCard from "../reactbits/vendor/SpotlightCard/SpotlightCard";
import { knowledgeBookById, practiceForBook } from "../knowledge/knowledgeCatalog";
import "../knowledge/knowledge.css";
import { loadCustomQuestions } from "./practiceCustomQuestions";
import { PRACTICE_TRACKS } from "./practiceTracks";

/**
 * 03 练习册的汇总页：四类练习（语音 / 词汇 / 结构 / 表达）各一本，
 * 只做题不讲知识；题量、已做、正确率都从题库和学习台账里实时算。
 * 对应第二层知识库的 /library 汇总，钢琴键「练习册」分区落到这里。
 */
export function PracticeLibraryPage() {
  const navigate = useNavigate();
  const hydrate = useKnowledge((state) => state.hydrate);
  const attempts = useKnowledge((state) => state.attempts);

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  const entries = useMemo(() => {
    const custom = loadCustomQuestions();
    return PRACTICE_TRACKS.map((track) => {
      const book = knowledgeBookById(track.bookId);
      const bankSize = book ? practiceForBook(book).length : 0;
      const bookAttempts = knowledgeAttemptsForBook(attempts, track.bookId);
      const done = bookAttempts.length;
      const correct = bookAttempts.filter((attempt) => attempt.correct).length;
      const accuracy = done ? Math.round((correct / done) * 100) : 0;
      const customCount = custom.filter(
        (question) => question.trackId === track.id,
      ).length;
      const lastAt = bookAttempts.reduce(
        (max, attempt) => Math.max(max, new Date(attempt.at).getTime()),
        0,
      );
      return { track, book, bankSize, done, accuracy, customCount, lastAt };
    });
  }, [attempts]);

  const totalQuestions = entries.reduce(
    (sum, entry) => sum + entry.bankSize + entry.customCount,
    0,
  );
  const answered = entries.reduce((sum, entry) => sum + entry.done, 0);
  const recents = [...entries]
    .filter((entry) => entry.lastAt > 0)
    .sort((left, right) => right.lastAt - left.lastAt)
    .slice(0, 3);

  return (
    <main className="knowledge-library">
      <header className="knowledge-library__header">
        <button
          type="button"
          className="knowledge-icon-button"
          onClick={() => navigate("/shelf")}
          aria-label="返回书房"
        >
          <ArrowLeft size={18} />
        </button>
        <div>
          <span className="knowledge-eyebrow">Practice · Drill collection</span>
          <h1>练习册</h1>
          <p>
            语音、词汇、结构、表达四本练习，只做题不讲知识；每道题当场对答判分，
            也可以自己出题。累计已做 {answered} 题。
          </p>
        </div>
        <span className="knowledge-library__count">
          <Layers3 size={15} />
          {totalQuestions} questions
        </span>
      </header>

      <section className="knowledge-books" aria-label="练习册列表">
        {entries.map(
          ({ track, book, bankSize, done, accuracy, customCount }) => {
            const progress = bankSize
              ? Math.min(100, Math.round((done / bankSize) * 100))
              : 0;
            return (
              <SpotlightCard
                as="article"
                key={track.id}
                className="knowledge-book-card"
                spotlightColor="rgba(47, 135, 171, 0.1)"
                style={
                  {
                    "--book-accent": track.accent,
                    "--book-secondary": `color-mix(in srgb, ${track.accent} 12%, white)`,
                  } as CSSProperties
                }
              >
                <button
                  type="button"
                  className="knowledge-book-card__cover"
                  onClick={() => navigate(`/drill/${track.id}`)}
                  aria-label={`打开 ${track.titleZh}练习`}
                >
                  <small>{book?.categoryId ?? "Practice"}</small>
                  <strong>{track.title}</strong>
                  <em>{track.titleZh}</em>
                </button>
                <div className="knowledge-book-card__copy">
                  <span className="knowledge-eyebrow">Drill volume</span>
                  <h2>{track.titleZh}</h2>
                  <p>{track.subtitleZh}</p>
                  <div className="knowledge-book-card__sources">
                    <span>
                      {book ? `来源 · ${book.zhTitle}` : "题库来源"}
                    </span>
                    <span>
                      {customCount > 0 ? `自建 ${customCount} 题` : "支持自己出题"}
                    </span>
                  </div>
                  <div className="knowledge-book-card__stats">
                    <span>
                      <strong>{bankSize}</strong>
                      questions
                    </span>
                    <span>
                      <strong>{done}</strong>
                      answered
                    </span>
                    <span>
                      <strong>{accuracy}%</strong>
                      correct
                    </span>
                  </div>
                  <div className="knowledge-book-card__progress">
                    <i style={{ width: `${progress}%` }} />
                  </div>
                  <button
                    type="button"
                    onClick={() => navigate(`/drill/${track.id}`)}
                  >
                    <SquarePen size={15} />
                    开始练习
                    <ArrowRight size={15} />
                  </button>
                  {book ? (
                    <button
                      type="button"
                      onClick={() => navigate(`/book/${book.id}`)}
                    >
                      <PenLine size={15} />
                      去看知识书
                    </button>
                  ) : null}
                </div>
              </SpotlightCard>
            );
          },
        )}
      </section>

      {recents.length > 0 ? (
        <section className="knowledge-recent">
          <header>
            <span className="knowledge-eyebrow">Keep drilling</span>
            <h2>继续练习</h2>
          </header>
          <div>
            {recents.map(({ track, accuracy }) => (
              <button
                type="button"
                key={track.id}
                onClick={() => navigate(`/drill/${track.id}`)}
              >
                <span style={{ background: track.accent }} />
                <strong>{track.title}</strong>
                <small>
                  {track.titleZh} · 正确率 {accuracy}%
                </small>
                <ArrowRight size={15} />
              </button>
            ))}
          </div>
        </section>
      ) : null}
    </main>
  );
}
